SELECT id, recipient_id, recipient_role, store_id, biz_type, biz_id,
       title, content, link, is_read, read_at, created_at
FROM notifications
WHERE recipient_id = #{recipientId}

    AND is_read = 0


    AND biz_type = #{bizType}

ORDER BY created_at DESC
LIMIT #{offset}, #{size}

